graphql.query:
query EventInfos($input: EventInfosInput) {
  eventInfos(input: $input) {
    count
    events {
      archived
      competition
      eventId
      eventType
      participants {
        abbreviation
        name
        role
        shortName
      }
      promoted
      shortTitle
      sport
      startTime
      startTimeIso
      status
      symbol
      title
    }
  }
}

query MarketFilterTreeV2 {
  marketFilterTreeV2 {
    filtersAsJson
  }
}

query TermsAndConditions {
  termsAndConditions {
    effectiveEndDate
    effectiveStartDate
    houseRules
    privacyPolicy
    termsAndConditions
    version
  }
}

mutation CancelOrder($orderId: rID!, $deviceInfo: DeviceInfo, $geoLocation: GeoLocationCode) {
  cancelOrder(orderId: $orderId, deviceInfo: $deviceInfo, geoLocation: $geoLocation) {
    nextGeolocationAt
    status
  }
}

mutation CancelOrders($deviceInfo: DeviceInfo, $geoLocation: GeoLocationCode, $orderIds: [rID]) {
  cancelOrders(deviceInfo: $deviceInfo, geoLocation: $geoLocation, orderIds: $orderIds) {
    nextGeolocationAt
    orderId
    status
  }
}

mutation CancelAllOrders($deviceInfo: DeviceInfo, $geoLocation: GeoLocationCode) {
  cancelAllOrders(deviceInfo: $deviceInfo, geoLocation: $geoLocation) {
    nextGeolocationAt
    orderId
    status
  }
}

mutation TncAccepted($input: TncAcceptanceInput!) {
  tncAccepted(input: $input)
}
